    items = query.split()

    # Initialize an ImagePatch object
    image_patch = ImagePatch(image)

    # Find patches for each item in the query
    patches = {item: image_patch.find(item) for item in items}

    # If an item is not found in the image, return a message
    for item, patch in patches.items():
        if not patch:
            return f"The item '{item}' was not found in the image."

    # If all items are found, return a message
    return "The items were found in the image."

